using System;
var r = new Register(); r.Add(4m); r.Add(6m); r.Clear(); r.Add(3m);
Console.WriteLine($"{r.Count} item, {r.Total:F2}");
class Register {
    public decimal Total { get; private set; }
    public int Count { get; private set; }
