using System;
int[] ids = { 2, 7, 10 };
Console.WriteLine(Count(ids, value => value >= 7));
Console.WriteLine(Count(ids, value => value % 2 == 0));
static int Count<T>(T[] values, Func<T, bool> test) {
    int count = 0;
    foreach (T value in values) if (test(value)) count++;
    return count;
}

